using System.Collections.Generic;
using Astrea.BattleActions;
using UnityEngine;

namespace Astrea.GameElements;

[CreateAssetMenu(fileName = "EnemyActionLogic_RandomCompanionTarget", menuName = "Data/Battle/Logics/Enemy Action/Random Companion Target")]
public class EnemyActionLogic_RandomCompanionTarget : EnemyActionLogic
{
	[Header("Units")]
	[SerializeField]
	private CurrentCompanions currentCompanions;

	public override void ActivateAction(BattleAction battleAction, int actionAmount, GameObject source)
	{
		base.ActivateAction(battleAction, actionAmount, source);
		List<GameObject> activeCompanions = currentCompanions.ActiveCompanions;
		if (activeCompanions.Count > 0)
		{
			GameObject target = activeCompanions.PickRandom();
			if (actionAmount == EffectsValues.NO_VALUE)
			{
				battleAction.CastTarget(target, source);
			}
			else
			{
				battleAction.CastTargetAmount(target, actionAmount, source);
			}
		}
	}
}
